#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main(void) {
    int v[4];

    for (int i = 0; i < 4; i++) {
        scanf("%d", &v[i]);
    }

    qsort(v, 4, sizeof(int), cmp);

    int d1 = abs((v[0] + v[1]) - (v[2] + v[3]));
    int d2 = abs((v[0] + v[2]) - (v[1] + v[3]));
    int d3 = abs((v[0] + v[3]) - (v[1] + v[2]));

    int ans = d1;
    if (d2 < ans) ans = d2;
    if (d3 < ans) ans = d3;

    printf("%d\n", ans);

    return 0;
}
